using System;using System.Linq;using System.Drawing;using System.Windows.Forms;using System.Reflection;using System.IO;
class OpeningMeetingChecks{
 [STAThread]static void Main(){var f=BindingFlags.Instance|BindingFlags.NonPublic;using(var g=new Game()){g.Show();var type=typeof(Game);var list=(System.Collections.Generic.List<Chapter>)type.GetField("chapters",f).GetValue(g);var c=list.Single(x=>x.id=="tavern-01-06");var s=(Save)type.GetField("save",f).GetValue(g);s.sectionAttempts[c.id]=new SectionAttempt{review=true,introShown=true};s.english=s.chinese=true;type.GetField("translating",f).SetValue(g,true);type.GetField("current",f).SetValue(g,c);type.GetField("index",f).SetValue(g,6);type.GetMethod("ShowStory",f).Invoke(g,null);Application.DoEvents();var stage=(ArtPanel)type.GetField("stage",f).GetValue(g);if(stage.Actors.Any(x=>x.Visible))throw new Exception("duplicate portraits on CG");for(int i=6;i<18;i++){type.GetField("index",f).SetValue(g,i);type.GetMethod("UpdateLine",f).Invoke(g,null);Application.DoEvents();if(stage.Actors.Any(x=>x.Visible))throw new Exception("CG portraits");}using(var b=new Bitmap(stage.Width,stage.Height)){stage.DrawToBitmap(b,stage.ClientRectangle);b.Save(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"opening-meeting-ui.png"));}type.GetField("index",f).SetValue(g,18);type.GetMethod("UpdateLine",f).Invoke(g,null);if(!stage.Actors.Any(x=>x.Visible))throw new Exception("original portraits not restored");type.GetField("index",f).SetValue(g,5);type.GetMethod("UpdateLine",f).Invoke(g,null);if(!stage.Actors.Any(x=>x.Visible))throw new Exception("previous scene");Console.WriteLine("PASS 12 CG lines use standard dialogue without portraits; next and previous original scenes restore portraits");}}
}
